const colors = ["#d2b19d", "#aec8bc", "#c5b6cf", "#b4c7d8", "#d8c49e"];
const $ = s => document.querySelector(s);
const money = n => new Intl.NumberFormat("en-IN", {style: "currency", currency: "INR", maximumFractionDigits: 0}).format(n);
function parseUTCDate(dtStr) {
if (!dtStr) return new Date(NaN);
if (!dtStr.endsWith("Z") && !dtStr.includes("+")) dtStr += "Z";
return new Date(dtStr);
}
let metrics = {};
let pendingLawyers = [];
let rejectedLawyers = [];
let approvedLawyersCount = 0;
let rejectedLawyersCount = 0;
let users = [];
let transactions = [];
let draftingTransactions = [];
let disputes = [];
let auditLogs = [];
let payouts = [];
let pendingPayouts = [];
let userFeedbacks = [];
let vouchers = [];
let currentVoucherFilter = "all";
const lawyerMap = {};
function checkAdminSession() {
const user = LexAPI.getCurrentUser();
const role = user ? String(user.role).toLowerCase() : "";
if (!user || role !== "admin") {
LexAPI.logout();
window.location.href = "admin-login.html";
return false;
}
return true;
}
if (!checkAdminSession()) {
throw new Error("Not authorized — redirecting to login.");
}
function mapPracticeToFrontend(p) {
if (Array.isArray(p)) return p.map(mapPracticeToFrontend).join(", ");
if (p === "property") return "Property Law";
if (p === "corporate") return "Corporate Law";
if (p === "family") return "Family Law";
return p;
}
function mapPracticeToBackend(p) {
if (Array.isArray(p)) return p.map(mapPracticeToBackend);
if (p === "Property Law") return "property";
if (p === "Corporate Law") return "corporate";
if (p === "Family Law") return "family";
return p;
}
function escapeHtml(text) {
return text
.replace(/&/g, "&amp;")
.replace(/</g, "&lt;")
.replace(/>/g, "&gt;")
.replace(/"/g, "&quot;")
.replace(/'/g, "&#039;");
}
async function loadData() {
try {
const [
metricsRes, pendingRes, rejectedRes, approvedRes, usersRes,
txRes, draftTxRes, disputesRes, auditRes, payoutsRes, pendingPayoutsRes, feedbackRes, vouchersRes
] = await Promise.allSettled([
LexAPI.metrics(),
LexAPI.getPendingLawyers(),
LexAPI.getRejectedLawyers(),
LexAPI.lawyers(),
LexAPI.getAdminUsers(),
LexAPI.getAdminTransactions(),
LexAPI.getAdminDraftingTransactions(),
LexAPI.getDisputes(),
LexAPI.getAuditLogs(),
LexAPI.getAdminPayouts(),
LexAPI.getPendingPayouts(),
LexAPI.getPlatformFeedback(),
LexAPI.getAdminVouchers()
]);
const val = (res, fallback) => res.status === "fulfilled" ? res.value : fallback;
// Check for critical authorization failures
const authFailure = [metricsRes, pendingRes, usersRes].find(
r => r.status === "rejected" && r.reason && r.reason.message &&
(r.reason.message.includes("401") || r.reason.message.includes("unauthorized") || r.reason.message.includes("authentication"))
);
if (authFailure) throw authFailure.reason;
metrics = val(metricsRes, {});
pendingLawyers = val(pendingRes, []);
rejectedLawyers = val(rejectedRes, []);
rejectedLawyersCount = rejectedLawyers.length;
const approvedList = val(approvedRes, []);
approvedLawyersCount = approvedList.length;
users = val(usersRes, []);
transactions = val(txRes, []);
draftingTransactions = val(draftTxRes, []);
disputes = val(disputesRes, []);
auditLogs = val(auditRes, []);
payouts = val(payoutsRes, []);
pendingPayouts = val(pendingPayoutsRes, []);
userFeedbacks = val(feedbackRes, []);
vouchers = val(vouchersRes, []);
renderAll();
updateBadgeCounts();
} catch (err) {
console.error("Failed to load admin console data:", err);
if (err.message && (err.message.includes("401") || err.message.includes("unauthorized") || err.message.includes("authentication"))) {
toast("Session expired or unauthorized. Redirecting to login...");
LexAPI.logout();
setTimeout(() => {
window.location.href = "admin-login.html";
}, 1500);
} else {
toast("Failed to load admin data: " + (err.message || "Server error"));
}
}
}
