const readyItems = (pendingPayouts || []).filter(p => (p.dispute_window_expired || p.entity_type === "draft") && p.payout_status !== "paid" && p.payout_status !== "held");
const totalHeldMinor = heldItems.reduce((sum, p) => sum + (p.amount_minor || 0), 0);
const totalReadyMinor = readyItems.reduce((sum, p) => sum + (p.amount_minor || 0), 0);
const totalBanks = (payouts || []).length;
const verifiedBanks = (payouts || []).filter(p => p.verified).length;
const statHeldEl = document.getElementById("stat-payout-held");
const statHeldSubEl = document.getElementById("stat-payout-held-sub");
