if (statHeldSubEl) statHeldSubEl.textContent = `${heldItems.length} ${heldItems.length === 1 ? 'item' : 'items'} in dispute hold`;
const statReadyEl = document.getElementById("stat-payout-ready");
const statReadySubEl = document.getElementById("stat-payout-ready-sub");
if (statReadyEl) statReadyEl.textContent = `₹${(totalReadyMinor / 100).toLocaleString('en-IN')}`;
if (statReadySubEl) statReadySubEl.textContent = `${readyItems.length} ${readyItems.length === 1 ? 'release' : 'releases'} ready for sweep`;
const statBanksEl = document.getElementById("stat-payout-banks");
const statBanksSubEl = document.getElementById("stat-payout-banks-sub");
if (statBanksEl) statBanksEl.textContent = `${totalBanks}`;
