// ── Vouchers & Promotions Management ──────────────────────────────────────────
function renderVouchers(filter = "all") {
currentVoucherFilter = filter;
const container = $("#vouchers-table");
if (!container) return;
const searchInput = document.getElementById("voucher-search");
if (searchInput && !searchInput.dataset.bound) {
searchInput.dataset.bound = "true";
searchInput.oninput = () => {
const activeTab = document.querySelector("#voucher-type-tabs button.active")?.dataset.voucherFilter || "all";
renderVouchers(activeTab);
};
}
const searchVal = (searchInput?.value || "").toLowerCase().trim();
// 1. Calculate Stat Metrics
const now = new Date();
const totalCount = vouchers.length;
const promoList = vouchers.filter(v => v.is_promotional);
const rebookList = vouchers.filter(v => !v.is_promotional);
const promoCount = promoList.length;
const rebookCount = rebookList.length;
const activePromoCount = promoList.filter(v => {
const isNotExp = !v.expires_at || new Date(v.expires_at) > now;
const hasUses = v.max_uses === 0 || (v.times_used || 0) < v.max_uses;
return v.is_active && !v.used && isNotExp && hasUses;
}).length;
const totalRedemptions = vouchers.reduce((sum, v) => sum + (v.times_used || 0), 0);
// Compute estimated discount savings from transactions that used a voucher
let totalSavingsPaise = 0;
transactions.forEach(t => {
if (t.voucher_code) {
const discPct = 20; // default benchmark
const grossPaid = t.amount_minor || 0;
totalSavingsPaise += Math.round(grossPaid * (discPct / (100 - discPct)));
}
});
// Update Stat Cards
const statActive = document.getElementById("stat-active-vouchers");
if (statActive) statActive.textContent = activePromoCount;
const statActiveSub = document.getElementById("stat-active-vouchers-sub");
if (statActiveSub) statActiveSub.textContent = `${activePromoCount} active · ${promoCount} total campaigns`;
const statRedemptions = document.getElementById("stat-total-redemptions");
if (statRedemptions) statRedemptions.textContent = totalRedemptions;
const statRedemptionsSub = document.getElementById("stat-total-redemptions-sub");
if (statRedemptionsSub) statRedemptionsSub.textContent = `${totalRedemptions} total application${totalRedemptions !== 1 ? 's' : ''}`;
const statSavings = document.getElementById("stat-total-discount-paise");
if (statSavings) statSavings.textContent = money(Math.round(totalSavingsPaise / 100));
// Update Tab and Nav Badges
const countAll = document.getElementById("voucher-count-all");
if (countAll) countAll.textContent = totalCount;
const countPromo = document.getElementById("voucher-count-promo");
if (countPromo) countPromo.textContent = promoCount;
const countRebook = document.getElementById("voucher-count-rebook");
if (countRebook) countRebook.textContent = rebookCount;
const navBadge = document.getElementById("voucher-nav-badge");
if (navBadge) navBadge.textContent = activePromoCount;
// 2. Filter dataset
let filtered = vouchers;
if (filter === "promotional") {
filtered = promoList;
} else if (filter === "rebooking") {
filtered = rebookList;
}
if (searchVal) {
filtered = filtered.filter(v => {
const code = (v.code || "").toLowerCase();
const desc = (v.description || "").toLowerCase();
return code.includes(searchVal) || desc.includes(searchVal);
});
}
// 3. Render Empty state or Table
if (!filtered || filtered.length === 0) {
container.innerHTML = `
<div class="empty" style="padding: 48px 24px; text-align: center; color: #718096; background: #ffffff; border-radius: 12px;">
<span style="font-size: 36px; display: inline-block; margin-bottom: 8px;">🏷️</span>
<p style="font-size: 15px; font-weight: 600; margin: 0 0 4px 0; color: #2d3748;">No vouchers match the criteria</p>
<small style="color: #a0aec0;">Click "Create Promo Code" to launch a new promotional discount campaign.</small>
</div>`;
return;
}
const rowsHtml = filtered.map(v => {
const isPromo = v.is_promotional;
const expDate = v.expires_at ? new Date(v.expires_at) : null;
const isExpired = expDate && expDate <= now;
const isExhausted = v.max_uses > 0 && (v.times_used || 0) >= v.max_uses;
let statusBadge = `<span style="background:#eef7f3; color:var(--forest); border:1px solid #bbf7d0; padding:4px 10px; border-radius:20px; font-size:11px; font-weight:700;">ACTIVE</span>`;
if (!v.is_active) {
statusBadge = `<span style="background:#fef2f2; color:#b91c1c; border:1px solid #fecaca; padding:4px 10px; border-radius:20px; font-size:11px; font-weight:700;">PAUSED</span>`;
} else if (isExpired) {
statusBadge = `<span style="background:#f3f4f6; color:#6b7280; border:1px solid #e5e7eb; padding:4px 10px; border-radius:20px; font-size:11px; font-weight:700;">EXPIRED</span>`;
} else if (isExhausted || v.used) {
statusBadge = `<span style="background:#fff7ed; color:#c2410c; border:1px solid #ffedd5; padding:4px 10px; border-radius:20px; font-size:11px; font-weight:700;">EXHAUSTED</span>`;
}
const typeBadge = isPromo
? `<span style="background:#f0fdf4; color:#166534; border:1px solid #bbf7d0; padding:3px 8px; border-radius:6px; font-size:11px; font-weight:700;">🏷️ PROMO CAMPAIGN</span>`
: `<span style="background:#f8fafc; color:#475569; border:1px solid #e2e8f0; padding:3px 8px; border-radius:6px; font-size:11px; font-weight:600;">🔄 REBOOK VOUCHER</span>`;
const maxUsesStr = v.max_uses === 0 ? "Unlimited" : v.max_uses;
const usesPct = v.max_uses > 0 ? Math.min(100, Math.round(((v.times_used || 0) / v.max_uses) * 100)) : 0;
let expStr = "No expiry";
if (expDate) {
expStr = expDate.toLocaleDateString("en-IN", {
day: "numeric",
month: "short",
year: "numeric"
});
}
const toggleBtnText = v.is_active ? "⏸ Pause" : "▶ Activate";
const toggleBtnStyle = v.is_active
? "background:#fff7ed; color:#c2410c; border:1px solid #ffedd5;"
: "background:#f0fdf4; color:#166534; border:1px solid #bbf7d0;";
return `
<tr style="border-bottom: 1px solid #f1f5f9; transition: background 0.15s ease;">
<td style="padding: 14px 16px; vertical-align: middle;">
<div style="display: flex; align-items: center; gap: 8px;">
<code style="font-family: monospace; font-weight: 800; font-size: 14px; background: #f1f5f9; padding: 4px 8px; border-radius: 6px; letter-spacing: 0.5px; color: #0f172a;">${escapeHtml(v.code)}</code>
<button type="button" onclick="copyVoucherCode('${escapeHtml(v.code)}')" title="Copy code" style="background:none; border:none; cursor:pointer; font-size:14px; padding:2px; color:var(--muted);">📋</button>
</div>
${v.description ? `<div style="font-size:12px; color:#64748b; margin-top:4px;">${escapeHtml(v.description)}</div>` : ''}
</td>
<td style="padding: 14px 16px; vertical-align: middle; white-space: nowrap;">
${typeBadge}
</td>
<td style="padding: 14px 16px; vertical-align: middle; white-space: nowrap;">
<span style="font-size: 15px; font-weight: 800; color: var(--forest); background: #ecfdf5; padding: 4px 10px; border-radius: 8px; border: 1px solid #a7f3d0;">
${v.discount_percent}% OFF
</span>
</td>
<td style="padding: 14px 16px; vertical-align: middle;">
<div style="font-size: 13px; font-weight: 700; color: #1e293b;">
${v.times_used || 0} <span style="font-weight: 400; color: #64748b;">/ ${maxUsesStr}</span>
</div>
${v.max_uses > 0 ? `
<div style="width: 80px; height: 5px; background: #e2e8f0; border-radius: 3px; margin-top: 5px; overflow: hidden;">
<div style="width: ${usesPct}%; height: 100%; background: var(--forest); border-radius: 3px;"></div>
</div>
` : ''}
</td>
<td style="padding: 14px 16px; vertical-align: middle; font-size: 13px; color: ${isExpired ? '#b91c1c' : '#334155'}; white-space: nowrap;">
${expStr} ${isExpired ? '<br><small style="font-size:10px; font-weight:700; color:#b91c1c;">EXPIRED</small>' : ''}
</td>
<td style="padding: 14px 16px; vertical-align: middle; white-space: nowrap;">
${statusBadge}
</td>
<td style="padding: 14px 16px; vertical-align: middle; text-align: right; white-space: nowrap;">
<div style="display: flex; gap: 6px; justify-content: flex-end;">
<button type="button" onclick="toggleVoucherStatus('${v.id}', ${!v.is_active})" style="padding: 5px 10px; font-size: 12px; font-weight: 700; border-radius: 6px; cursor: pointer; ${toggleBtnStyle}">
${toggleBtnText}
</button>
<button type="button" onclick="deleteVoucher('${v.id}', '${escapeHtml(v.code)}')" style="padding: 5px 10px; font-size: 12px; font-weight: 600; border-radius: 6px; cursor: pointer; background: #fff; border: 1px solid #e2e8f0; color: #ef4444;" title="Delete voucher">
🗑️
</button>
</div>
</td>
</tr>
`;
}).join("");
container.innerHTML = `
<table style="width: 100%; border-collapse: collapse; text-align: left;">
<thead>
<tr style="background: #f8fafc; border-bottom: 2px solid #e2e8f0;">
<th style="padding: 12px 16px; font-size: 12px; font-weight: 700; text-transform: uppercase; color: #475569; letter-spacing: 0.5px;">Code & Campaign</th>
<th style="padding: 12px 16px; font-size: 12px; font-weight: 700; text-transform: uppercase; color: #475569; letter-spacing: 0.5px;">Type</th>
<th style="padding: 12px 16px; font-size: 12px; font-weight: 700; text-transform: uppercase; color: #475569; letter-spacing: 0.5px;">Discount</th>
<th style="padding: 12px 16px; font-size: 12px; font-weight: 700; text-transform: uppercase; color: #475569; letter-spacing: 0.5px;">Redemptions</th>
<th style="padding: 12px 16px; font-size: 12px; font-weight: 700; text-transform: uppercase; color: #475569; letter-spacing: 0.5px;">Expires</th>
<th style="padding: 12px 16px; font-size: 12px; font-weight: 700; text-transform: uppercase; color: #475569; letter-spacing: 0.5px;">Status</th>
<th style="padding: 12px 16px; font-size: 12px; font-weight: 700; text-transform: uppercase; color: #475569; letter-spacing: 0.5px; text-align: right;">Actions</th>
</tr>
</thead>
<tbody>
${rowsHtml}
</tbody>
</table>`;
}
window.copyVoucherCode = (code) => {
if (navigator.clipboard) {
navigator.clipboard.writeText(code).then(() => {
toast(`Code "${code}" copied to clipboard!`);
}).catch(() => {
toast(`Code: ${code}`);
});
} else {
toast(`Code: ${code}`);
}
};
window.toggleVoucherStatus = async (id, newActive) => {
try {
await LexAPI.toggleAdminVoucher(id, newActive);
toast(`Voucher status updated (${newActive ? 'Activated' : 'Paused'}).`);
loadData();
} catch (err) {
toast("Failed to update voucher status: " + err.message);
}
};
window.deleteVoucher = async (id, code) => {
if (!confirm(`Are you sure you want to permanently delete voucher "${code}"?`)) return;
try {
await LexAPI.deleteAdminVoucher(id);
toast(`Voucher "${code}" deleted successfully.`);
loadData();
} catch (err) {
toast("Failed to delete voucher: " + err.message);
}
};
// ── Voucher Modal & Creation Events ──────────────────────────────────────────
function initVoucherModalEvents() {
const modal = document.getElementById("voucher-modal");
const openBtn = document.getElementById("btn-open-create-voucher");
const closeBtn = document.getElementById("btn-close-voucher-modal");
const cancelBtn = document.getElementById("btn-cancel-voucher");
const form = document.getElementById("create-voucher-form");
const pctSlider = document.getElementById("new-voucher-pct");
const pctLabel = document.getElementById("discount-val-label");
const expiryInput = document.getElementById("new-voucher-expiry");
const errEl = document.getElementById("voucher-form-error");
// Ensure modal is cleanly hidden on initialization
if (modal && modal.hidden) {
modal.style.display = "none";
}
const openModal = () => {
if (!modal) return;
if (form) form.reset();
if (errEl) errEl.textContent = "";
// Set default expiry date to +30 days
if (expiryInput) {
const defaultExp = new Date();
defaultExp.setDate(defaultExp.getDate() + 30);
expiryInput.value = defaultExp.toISOString().slice(0, 10);
expiryInput.min = new Date().toISOString().slice(0, 10);
}
if (pctSlider && pctLabel) {
pctSlider.value = "20";
pctLabel.textContent = "20% OFF";
}
// Highlight 20% preset
document.querySelectorAll(".preset-pct-btn").forEach(btn => {
const is20 = btn.dataset.pct === "20";
btn.style.background = is20 ? "#eef7f3" : "#f8fafc";
btn.style.borderColor = is20 ? "var(--forest)" : "var(--line)";
btn.style.color = is20 ? "var(--forest)" : "var(--ink)";
});
modal.hidden = false;
modal.style.display = "flex";
document.body.style.overflow = "hidden";
setTimeout(() => document.getElementById("new-voucher-code")?.focus(), 100);
};
const closeModal = () => {
if (modal) {
modal.hidden = true;
modal.style.display = "none";
document.body.style.overflow = "";
}
};
if (openBtn) openBtn.onclick = openModal;
if (closeBtn) {
closeBtn.onclick = (e) => {
if (e) { e.preventDefault(); e.stopPropagation(); }
closeModal();
};
}
if (cancelBtn) {
cancelBtn.onclick = (e) => {
if (e) { e.preventDefault(); e.stopPropagation(); }
closeModal();
};
}
// Close on clicking backdrop outside modal content
if (modal) {
modal.onclick = (e) => {
if (e.target === modal) {
closeModal();
}
};
}
// Close on Escape key press
document.addEventListener("keydown", (e) => {
if (e.key === "Escape" && modal && !modal.hidden && modal.style.display !== "none") {
closeModal();
}
});
// Percentage slider change
if (pctSlider && pctLabel) {
pctSlider.oninput = (e) => {
const val = e.target.value;
pctLabel.textContent = `${val}% OFF`;
document.querySelectorAll(".preset-pct-btn").forEach(btn => {
const matches = btn.dataset.pct === val;
btn.style.background = matches ? "#eef7f3" : "#f8fafc";
btn.style.borderColor = matches ? "var(--forest)" : "var(--line)";
btn.style.color = matches ? "var(--forest)" : "var(--ink)";
});
};
}
// Preset discount buttons
document.querySelectorAll(".preset-pct-btn").forEach(btn => {
btn.onclick = () => {
const pct = btn.dataset.pct;
if (pctSlider) pctSlider.value = pct;
if (pctLabel) pctLabel.textContent = `${pct}% OFF`;
document.querySelectorAll(".preset-pct-btn").forEach(b => {
const matches = b === btn;
b.style.background = matches ? "#eef7f3" : "#f8fafc";
b.style.borderColor = matches ? "var(--forest)" : "var(--line)";
b.style.color = matches ? "var(--forest)" : "var(--ink)";
});
};
});
// Auto uppercase code input
const codeInput = document.getElementById("new-voucher-code");
if (codeInput) {
codeInput.oninput = (e) => {
e.target.value = e.target.value.toUpperCase().replace(/[^A-Z0-9\-_]/g, "");
};
}
// Form submit
if (form) {
form.onsubmit = async (e) => {
e.preventDefault();
if (errEl) errEl.textContent = "";
const code = (document.getElementById("new-voucher-code")?.value || "").trim().toUpperCase();
const discountPercent = parseInt(pctSlider?.value, 10) || 20;
const maxUses = parseInt(document.getElementById("new-voucher-max-uses")?.value, 10) || 0;
const expiryVal = document.getElementById("new-voucher-expiry")?.value;
const description = (document.getElementById("new-voucher-desc")?.value || "").trim() || null;
if (!code || code.length < 3) {
if (errEl) errEl.textContent = "Voucher code must be at least 3 characters.";
return;
}
if (!expiryVal) {
if (errEl) errEl.textContent = "Please select an expiry date.";
return;
}
const submitBtn = document.getElementById("btn-submit-voucher");
if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = "Saving..."; }
try {
const expDate = new Date(expiryVal + "T23:59:59Z");
const payload = {
code,
discount_percent: discountPercent,
expires_at: expDate.toISOString(),
max_uses: maxUses,
description
};
await LexAPI.createAdminVoucher(payload);
toast(`Promotional code "${code}" created with ${discountPercent}% discount!`);
closeModal();
loadData();
} catch (err) {
if (errEl) errEl.textContent = err.message || "Failed to create voucher.";
} finally {
if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = "Save & Activate Voucher"; }
}
};
}
// Tab filter switching
const tabContainer = document.getElementById("voucher-type-tabs");
if (tabContainer) {
tabContainer.onclick = (e) => {
const btn = e.target.closest("button[data-voucher-filter]");
if (!btn) return;
tabContainer.querySelectorAll("button").forEach(b => b.classList.remove("active"));
btn.classList.add("active");
renderVouchers(btn.dataset.voucherFilter);
};
}
}
// Call after loading DOM
document.addEventListener("DOMContentLoaded", initVoucherModalEvents);
initVoucherModalEvents();
loadData();